const HuffmanCodebook& huffmanCodebook(unsigned index) {
    static const HuffmanCodebook kEmpty{0, 0, false, false, nullptr, 0};
    return index < 12 ? kCodebooks[index] : kEmpty;
}

ScaleFactorBands longBands(uint8_t sample_rate_index) {
    if (sample_rate_index >= 13) {
        return ScaleFactorBands{};
    }
    return ScaleFactorBands{kLongOffsets[sample_rate_index], kLongCounts[sample_rate_index]};
}

ScaleFactorBands shortBands(uint8_t sample_rate_index) {
    if (sample_rate_index >= 13) {
        return ScaleFactorBands{};
    }
    return ScaleFactorBands{kShortOffsets[sample_rate_index], kShortCounts[sample_rate_index]};
}

uint8_t tnsMaxBandsLong(uint8_t sample_rate_index) {
    return sample_rate_index < 13 ? kTnsLong[sample_rate_index] : 0;
}

uint8_t tnsMaxBandsShort(uint8_t sample_rate_index) {
    return sample_rate_index < 13 ? kTnsShort[sample_rate_index] : 0;
}

const float* tnsCoefficients(unsigned index) {
    return index < 4 ? kTnsCoefficients[index] : nullptr;
}

